<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($appName, ENT_QUOTES, 'UTF-8') ?> — <?= $member === null ? 'Add' : 'Edit' ?> member</title><link rel="stylesheet" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/assets/app.css"></head>
<body><header class="app-header"><p class="brand">ZPM Membership Management</p><div class="user-menu"><span><?= htmlspecialchars($user['full_name'], ENT_QUOTES, 'UTF-8') ?></span></div></header><div class="layout"><?php require __DIR__ . '/partials/nav.php'; ?><main class="main"><h1><?= $member === null ? 'Add member' : 'Edit member' ?></h1><section class="content-card"><form method="post" action="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/members" data-prevent-repeat="true"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><?php if ($member !== null): ?><input type="hidden" name="id" value="<?= (int) $member['id'] ?>"><?php endif; ?><div class="form-grid"><div class="field"><label for="full_name">Full name</label><input id="full_name" name="full_name" required value="<?= htmlspecialchars($member['full_name'] ?? '', ENT_QUOTES, 'UTF-8') ?>"></div><div class="field"><label for="gender">Gender</label><select id="gender" name="gender"><?php foreach (['female','male','not-specified'] as $gender): ?><option value="<?= $gender ?>" <?= ($member['gender'] ?? 'not-specified') === $gender ? 'selected' : '' ?>><?= ucfirst(str_replace('-', ' ', $gender)) ?></option><?php endforeach; ?></select></div><div class="field"><label for="enrollment_date">Enrollment date</label><input id="enrollment_date" name="enrollment_date" type="date" required max="<?= date('Y-m-d') ?>" value="<?= htmlspecialchars($member['enrollment_date'] ?? date('Y-m-d'), ENT_QUOTES, 'UTF-8') ?>"></div><div class="field"><label for="membership_status">Membership status</label><select id="membership_status" name="membership_status"><?php foreach (['active','inactive','resigned','deceased','archived'] as $status): ?><option value="<?= $status ?>" <?= ($member['membership_status'] ?? 'active') === $status ? 'selected' : '' ?>><?= ucfirst($status) ?></option><?php endforeach; ?></select></div><div class="field field-wide"><label for="current_unit_id">Organizational unit</label><select id="current_unit_id" name="current_unit_id" required><option value="">Select a unit</option><?php foreach ($unitOptions as $unit): ?><option value="<?= (int) $unit['id'] ?>" <?= (int) ($member['current_unit_id'] ?? 0) === (int) $unit['id'] ? 'selected' : '' ?>><?= htmlspecialchars($unit['district_name'] . ' / ' . $unit['block_name'] . ' / ' . $unit['unit_name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></div><div class="field field-wide"><label for="remarks">Administrative remarks</label><textarea id="remarks" name="remarks" rows="4"><?= htmlspecialchars($member['remarks'] ?? '', ENT_QUOTES, 'UTF-8') ?></textarea></div></div><button type="submit">Save member</button> <a class="button-link" href="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/members">Cancel</a></form></section></main></div><script src="<?= htmlspecialchars($basePath, ENT_QUOTES, 'UTF-8') ?>/assets/app.js"></script></body></html>
